// NULL-tolerant scan buffer for matchPlayerScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type matchPlayerPreloadBuf struct {
	ID           null.Val[int64]
	MatchID      null.Val[int64]
	PlayerID     null.Val[int64]
	Score        null.Val[int32]
	Placement    null.Val[int32]
	IsWinner     null.Val[bool]
	RoundsPlayed null.Val[int32]
}

// matchPlayerScanMapperNullable maps the preloaded matchPlayer
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func matchPlayerScanMapperNullable(prefix string) scan.Mapper[*MatchPlayer] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*MatchPlayer, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *matchPlayerPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.ID }})
			case "match_id":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.MatchID }})
			case "player_id":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.PlayerID }})
			case "score":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.Score }})
			case "placement":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.Placement }})
			case "is_winner":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.IsWinner }})
			case "rounds_played":
				targets = append(targets, target{i, func(b *matchPlayerPreloadBuf) any { return &b.RoundsPlayed }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(matchPlayerPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*MatchPlayer, error) {
				buf := link.(*matchPlayerPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.MatchID.IsValue()) &&
					!(buf.PlayerID.IsValue()) &&
					!(buf.Score.IsValue()) &&
					!(buf.Placement.IsValue()) &&
					!(buf.IsWinner.IsValue()) &&
					!(buf.RoundsPlayed.IsValue()) {
					return nil, nil
				}

				o := new(MatchPlayer)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.MatchID.IsValue() {
					o.MatchID = buf.MatchID.MustGet()
				}
				if buf.PlayerID.IsValue() {
					o.PlayerID = buf.PlayerID.MustGet()
				}
				if buf.Score.IsValue() {
					o.Score = buf.Score.MustGet()
				}
				o.Placement = buf.Placement
				if buf.IsWinner.IsValue() {
					o.IsWinner = buf.IsWinner.MustGet()
				}
				if buf.RoundsPlayed.IsValue() {
					o.RoundsPlayed = buf.RoundsPlayed.MustGet()
				}
				return o, nil
			}
	}
}

func (o *MatchPlayer) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "MatchPlayerSessions":
		rels, ok := retrieved.(MatchPlayerSessionSlice)
		if !ok {
			return fmt.Errorf("matchPlayer cannot load %T as %q", retrieved, name)
		}

		o.R.MatchPlayerSessions = rels
		o.R.Loaded.MatchPlayerSessions = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.MatchPlayer = o
				rel.R.Loaded.MatchPlayer = true
			}
		}
		return nil
	case "Match":
		rel, ok := retrieved.(*Match)
		if !ok {
			return fmt.Errorf("matchPlayer cannot load %T as %q", retrieved, name)
		}

		o.R.Match = rel
		o.R.Loaded.Match = true

		if rel != nil {
			rel.R.MatchPlayers = MatchPlayerSlice{o}
		}
		return nil
	case "Player":
		rel, ok := retrieved.(*Player)
		if !ok {
			return fmt.Errorf("matchPlayer cannot load %T as %q", retrieved, name)
		}

		o.R.Player = rel
		o.R.Loaded.Player = true

		if rel != nil {
			rel.R.MatchPlayers = MatchPlayerSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("matchPlayer has no relationship %q", name)
	}
}

