// LoadMatchPlayerSessions loads the matchPlayer's MatchPlayerSessions into the .R struct
func (o *MatchPlayer) LoadMatchPlayerSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.MatchPlayerSessions = nil
	o.R.Loaded.MatchPlayerSessions = false

	related, err := o.MatchPlayerSessions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.MatchPlayer = o
		rel.R.Loaded.MatchPlayer = true
	}

	o.R.MatchPlayerSessions = related
	o.R.Loaded.MatchPlayerSessions = true
	return nil
}

// LoadMatchPlayerSessions loads the matchPlayer's MatchPlayerSessions into the .R struct
func (os MatchPlayerSlice) LoadMatchPlayerSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	matchPlayerSessions, err := os.MatchPlayerSessions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.MatchPlayerSessions = nil
		o.R.Loaded.MatchPlayerSessions = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	matchPlayerByKey := make(map[int64][]*MatchPlayer, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		matchPlayerByKey[o.ID] = append(matchPlayerByKey[o.ID], o)
	}

	for _, rel := range matchPlayerSessions {

		owners, ok := matchPlayerByKey[rel.MatchPlayerID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.MatchPlayer = o
			rel.R.Loaded.MatchPlayer = true

			o.R.MatchPlayerSessions = append(o.R.MatchPlayerSessions, rel)

		}
	}

	return nil
}

